From ad96710c595787e0c9fa6ee1f8aebd6044d6a450 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:08:40 +0100
Subject: [PATCH] containmentactions/contextmenu: add optional Applications
 submenu

The application menu could only be bound to a mouse button on its own,
replacing the standard menu. Add an Applications entry, off by default,
that people can enable in the standard menu to browse and launch apps.

BUG: 479282
---
 containmentactions/contextmenu/menu.cpp | 38 +++++++++++++++++++++++++
 containmentactions/contextmenu/menu.h   |  6 ++++
 2 files changed, 44 insertions(+)

diff --git a/containmentactions/contextmenu/menu.cpp b/containmentactions/contextmenu/menu.cpp
index 7097e442cf..5c52a59730 100644
--- a/containmentactions/contextmenu/menu.cpp
+++ b/containmentactions/contextmenu/menu.cpp
@@ -60,6 +60,7 @@ void ContextMenu::restore(const KConfigGroup &config)
         actions.insert(QStringLiteral("configure shortcuts"), false);
         m_actionOrder << QStringLiteral("_context")
                       << QStringLiteral("_sep1")
+                      << QStringLiteral("_applications")
                       << QStringLiteral("configure shortcuts")
                       << QStringLiteral("_open_terminal")
                       << QStringLiteral("_run_command")
@@ -82,6 +83,7 @@ void ContextMenu::restore(const KConfigGroup &config)
                       << QStringLiteral("_sep4")
                       << QStringLiteral("configure")
                       << QStringLiteral("_display_settings");
+        disabled.insert(QStringLiteral("_applications"));
         disabled.insert(QStringLiteral("add widgets"));
         disabled.insert(QStringLiteral("_add panel"));
         disabled.insert(QStringLiteral("configure shortcuts"));
@@ -109,6 +111,16 @@ void ContextMenu::restore(const KConfigGroup &config)
         m_runCommandAction->setShortcut(KGlobalAccel::self()->globalShortcut(QStringLiteral("org.kde.krunner.desktop"), QStringLiteral("_launch")).value(0));
         connect(m_runCommandAction, &QAction::triggered, this, &ContextMenu::runCommand);

+        m_applicationsAction = new QAction(i18nc("plasma_containmentactions_contextmenu", "Applications"), this);
+        m_applicationsAction->setIcon(QIcon::fromTheme(u"applications-all-symbolic"_s));
+        m_applicationsMenu = std::make_unique<QMenu>();
+        connect(m_applicationsMenu.get(), &QMenu::aboutToShow, this, [this]() {
+            qDeleteAll(m_applicationsMenu->findChildren<QMenu *>(Qt::FindDirectChildrenOnly));
+            m_applicationsMenu->clear();
+            fillApplicationsMenu(m_applicationsMenu.get(), KServiceGroup::root());
+        });
+        m_applicationsAction->setMenu(m_applicationsMenu.get());
+
         m_openTerminalAction = new QAction(i18n("Open Terminal"), this);
         m_openTerminalAction->setIcon(QIcon::fromTheme(u"utilities-terminal-symbolic"_s));
         connect(m_openTerminalAction, &QAction::triggered, this, &ContextMenu::openTerminal);
@@ -199,6 +211,8 @@ QAction *ContextMenu::action(const QString &name)
         if (KAuthorized::authorizeAction(QStringLiteral("run_command")) && KAuthorized::authorize(QStringLiteral("run_command"))) {
             return m_runCommandAction;
         }
+    } else if (name == QLatin1String("_applications")) {
+        return m_applicationsAction;
     } else if (name == QLatin1String("_open_terminal")) {
         if (KAuthorized::authorizeAction(QStringLiteral("shell_access"))) {
             return m_openTerminalAction;
@@ -236,6 +250,30 @@ QAction *ContextMenu::action(const QString &name)
     return nullptr;
 }

+void ContextMenu::fillApplicationsMenu(QMenu *menu, const KServiceGroup::Ptr &group)
+{
+    const auto entries = group->entries(true, true, true);
+    for (const KSycocaEntry::Ptr &p : entries) {
+        if (p->isType(KST_KService)) {
+            const KService::Ptr service(static_cast<KService *>(p.data()));
+            QAction *action = menu->addAction(QIcon::fromTheme(service->icon()), service->name().replace(u'&', u"&&"_s));
+            connect(action, &QAction::triggered, this, [service]() {
+                auto job = new KIO::ApplicationLauncherJob(service);
+                job->start();
+            });
+        } else if (p->isType(KST_KServiceGroup)) {
+            const KServiceGroup::Ptr subGroup(static_cast<KServiceGroup *>(p.data()));
+            if (subGroup->childCount() == 0) {
+                continue;
+            }
+            QMenu *subMenu = menu->addMenu(QIcon::fromTheme(subGroup->icon()), subGroup->caption().replace(u'&', u"&&"_s));
+            fillApplicationsMenu(subMenu, subGroup);
+        } else if (p->isType(KST_KServiceSeparator)) {
+            menu->addSeparator();
+        }
+    }
+}
+
 void ContextMenu::openTerminal()
 {
     if (!KAuthorized::authorizeAction(QStringLiteral("shell_access"))) {
